INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (208, 1, 'ConfigMap 만드는 세 가지 방법', '`kubectl create cm c1 --from-literal=k1=v1`, `--from-file=app.conf`, `--from-file=mykey=app.conf` 로 만들면 키 이름은 각각 무엇이 될까요?', '파일에서 만들면 기본 키는 파일 이름이에요.', NULL, NULL, '[]', 'choice', '["세 방식 모두 키는 `data` 가 된다", "`--from-file` 은 키가 항상 `file` 이 된다", "`--from-literal=k1=v1` 은 `k1`, `--from-file=app.conf` 는 파일 이름인 `app.conf`, `--from-file=mykey=app.conf` 는 `mykey` 가 키가 되고 값은 파일 내용이다", "`--from-file=mykey=app.conf` 는 `mykey=app.conf` 전체가 키가 된다"]', 2, '`--from-env-file` 은 `A=1` 같은 줄마다 키와 값을 만듭니다.', NULL, NULL, NULL, NULL),
  (208, 2, '이미 있는 ConfigMap 만들기', '이미 있는 ConfigMap `c1` 과 같은 이름으로 `kubectl create cm c1 --from-literal=x=y` 를 하면 어떻게 될까요?', 'create 는 새로 만들기만 해요.', NULL, NULL, '[]', 'choice', '["기존 내용에 `x=y` 가 덮어써진다", "`already exists` 오류가 나고 기존 내용은 그대로이다. 고치려면 `patch` 나 `edit` 를 쓰거나 지우고 다시 만든다", "이름 뒤에 번호가 붙은 새 ConfigMap 이 만들어진다", "오류 없이 아무것도 하지 않는다"]', 1, '값만 바꾸려면 `kubectl patch cm c1 --type merge -p` 처럼 일부만 고칠 수 있습니다.', NULL, NULL, NULL, NULL),
  (208, 3, 'Secret 의 base64', '`kubectl create secret generic s1 --from-literal=user=admin` 으로 만든 Secret 의 `.data.user` 는 무엇일까요? `kubectl describe secret s1` 은 값을 보여 줄까요?', '저장은 base64 로 해요.', NULL, NULL, '[]', 'choice', '["`.data.user` 는 `admin` 이 아니라 base64 로 바뀐 `YWRtaW4=` 이고 `base64 -d` 로 되돌릴 수 있어 암호화가 아니다. `describe` 는 값 대신 `user:  5 bytes` 처럼 크기만 보여 준다", "`.data.user` 는 `admin` 그대로 저장된다", "`.data.user` 는 되돌릴 수 없게 암호화된다", "`describe` 는 값을 평문으로 보여 준다"]', 0, 'Secret 은 읽기 권한을 제한하는 것이 중요합니다. base64 만으로는 보호가 되지 않습니다.', NULL, NULL, NULL, NULL),
  (208, 4, 'stringData', 'Secret YAML 에 `stringData: {token: plain-text}` 를 쓰고 `apply` 하면 저장된 모습은 어떨까요? 같은 키가 `data` 와 `stringData` 에 모두 있으면요?', 'stringData 는 쓰기용 편의 필드예요.', NULL, NULL, '[]', 'choice', '["`stringData` 는 평문 그대로 저장되어 조회해도 보인다", "같은 키가 둘 다 있으면 `data` 의 값이 쓰인다", "`stringData` 는 `apply` 할 때 오류가 난다", "`stringData` 의 값이 base64 로 바뀌어 `data` 에 저장되고, 조회하면 `stringData` 는 나오지 않는다. 같은 키가 둘 다 있으면 `stringData` 의 값이 쓰인다"]', 3, '평문 값을 직접 base64 로 바꾸지 않아도 되어 편합니다.', NULL, NULL, NULL, NULL),
  (208, 5, '환경 변수로 쓰기', 'Pod 에서 ConfigMap `c4` 의 모든 키를 환경 변수로 넣고, ConfigMap `c1` 의 키 `k1` 하나만 변수 `K1` 로 넣으려면 각각 무엇을 쓸까요?', '전체는 envFrom, 하나는 valueFrom 이에요.', NULL, NULL, '[]', 'choice', '["둘 다 `volumes` 아래에 적는다", "전체는 `configMapKeyRef`, 하나는 `configMapRef` 를 쓴다", "전체 키는 `envFrom` 아래의 `configMapRef`, 키 하나는 `env` 아래의 `valueFrom.configMapKeyRef` 를 쓴다. `envFrom` 에 `prefix: CFG_` 를 주면 변수 이름 앞에 붙는다", "ConfigMap 은 환경 변수로 쓸 수 없고 볼륨으로만 쓸 수 있다"]', 2, 'Secret 은 `secretRef`, `secretKeyRef` 로 같은 방식입니다.', NULL, NULL, NULL, NULL),
  (208, 6, '볼륨으로 마운트하면', 'ConfigMap `c1` 에 키 `k1`, `k2` 가 있고 이것을 `/cfg` 에 볼륨으로 마운트하면 Pod 안에는 무엇이 보일까요?', '키마다 파일이 하나씩 생겨요.', NULL, NULL, '[]', 'choice', '["`/cfg` 에 `c1` 이라는 파일 하나만 생기고 안에 모든 값이 들어 있다", "`/cfg/k1`, `/cfg/k2` 파일이 생기고 각 파일의 내용이 키의 값이다", "`/cfg` 가 비어 있고 환경 변수로만 값을 읽을 수 있다", "`k1`, `k2` 가 폴더가 되고 값은 폴더 이름이 된다"]', 1, '키 이름이 곧 파일 이름이므로 파일 이름으로 쓸 수 있는 키여야 합니다.', NULL, NULL, NULL, NULL),
  (208, 7, 'ConfigMap·Secret 볼륨은 읽기 전용', 'Pod 안에서 ConfigMap 볼륨이나 Secret 볼륨의 파일에 `echo x > /cfg/k1` 로 쓰면 어떻게 될까요?', 'Pod 안에서는 고칠 수 없어요.', NULL, NULL, '[]', 'choice', '["`Read-only file system` 오류가 난다. 내용을 바꾸려면 ConfigMap 이나 Secret 자체를 수정해야 한다", "파일이 바뀌고 ConfigMap 에도 반영된다", "파일은 바뀌지만 ConfigMap 은 그대로이다", "파일이 새로 만들어지고 기존 파일은 `k1.bak` 이 된다"]', 0, '`volumeMounts` 의 `readOnly: true` 는 다른 종류의 볼륨까지 읽기 전용으로 만들 때 씁니다.', NULL, NULL, NULL, NULL),
  (208, 8, 'Secret 파일 권한', 'Secret 볼륨에 `defaultMode: 0400` 을 주면 마운트된 파일의 권한은 어떻게 될까요?', '숫자는 chmod 와 같은 8진수예요.', NULL, NULL, '[]', 'choice', '["파일이 숨김 파일이 된다", "Pod 를 만들 수 없다는 오류가 난다", "Secret 의 값이 암호화되어 읽을 수 없게 된다", "파일 권한이 소유자 읽기만 가능한 `-r--------` 가 된다. 기본 권한보다 더 좁게 제한할 수 있다"]', 3, '`defaultMode` 는 볼륨 안의 모든 파일에 적용됩니다.', NULL, NULL, NULL, NULL),
  (208, 9, 'ConfigMap 을 고치면 Pod 에는', 'Pod 가 ConfigMap `c1` 의 `k1` 을 환경 변수로도 쓰고 `/cfg` 볼륨으로도 마운트했습니다. `k1` 을 `v1-NEW` 로 고치면 실행 중인 Pod 는 어떻게 될까요?', '환경 변수는 시작할 때 한 번 정해져요.', NULL, NULL, '[]', 'choice', '["둘 다 즉시 바뀐다", "둘 다 바뀌지 않는다", "환경 변수는 Pod 가 시작할 때 정해져서 그대로이고, 볼륨의 `/cfg/k1` 파일은 시간이 조금 지난 뒤(우리 시험에서는 약 1분 반 안) `v1-NEW` 로 바뀐다. 환경 변수를 바꾸려면 Pod 를 다시 시작해야 한다", "환경 변수는 바뀌고 볼륨 파일은 그대로이다"]', 2, '그래서 설정 변경 후에는 보통 `kubectl rollout restart` 로 Pod 를 다시 만듭니다.', NULL, NULL, NULL, NULL),
  (208, 10, 'subPath 로 마운트하면', 'ConfigMap `c2` 의 `app.conf` 한 파일만 `mountPath: /one/app.conf`, `subPath: app.conf` 로 마운트했습니다. ConfigMap 을 고치면 이 파일은 어떻게 될까요?', 'subPath 는 한 파일만 떼어 마운트해요.', NULL, NULL, '[]', 'choice', '["일반 볼륨처럼 시간이 지나면 갱신된다", "`subPath` 로 마운트한 파일은 ConfigMap 이 바뀌어도 갱신되지 않고 처음 내용 그대로이다. 갱신되게 하려면 폴더째 마운트한다", "ConfigMap 이 바뀌면 Pod 가 자동으로 다시 만들어진다", "ConfigMap 을 고칠 수 없게 잠긴다"]', 1, '`subPath` 는 폴더의 기존 파일을 가리지 않고 파일 하나만 끼워 넣을 때 씁니다.', NULL, NULL, NULL, NULL),
  (208, 11, 'immutable ConfigMap', '`immutable: true` 인 ConfigMap 의 `data` 를 `patch` 로 바꾸려 하면 어떻게 될까요?', '한 번 정하면 바꿀 수 없게 하는 필드예요.', NULL, NULL, '[]', 'choice', '["`field is immutable when immutable is set` 오류로 거부된다. 값을 바꾸려면 ConfigMap 을 지우고 다시 만든다", "조용히 바뀐다", "값은 바뀌지만 Pod 에는 반영되지 않는다", "`immutable` 은 `data` 가 아니라 이름만 막는다"]', 0, '실수로 바뀌는 것을 막고 갱신 확인 부담을 줄이려고 씁니다.', NULL, NULL, NULL, NULL),
  (208, 12, '없는 ConfigMap 참조', '존재하지 않는 ConfigMap 을 환경 변수로 참조한 Pod 와, 볼륨으로 마운트한 Pod 는 각각 어떤 상태가 될까요? 볼륨에 `optional: true` 를 주면요?', '환경 변수와 볼륨의 실패 모습이 달라요.', NULL, NULL, '[]', 'choice', '["둘 다 `Running` 이 되고 값만 비어 있다", "둘 다 `Completed` 가 된다", "환경 변수 참조만 `FailedMount` 가 난다", "환경 변수 참조는 `CreateContainerConfigError`, 볼륨 마운트는 `ContainerCreating` 에 머물며 `FailedMount` 이벤트가 난다. 볼륨에 `optional: true` 를 주면 없어도 `Running` 이 된다"]', 3, '`kubectl describe pod` 의 Events 에서 원인을 확인합니다.', NULL, NULL, NULL, NULL),
  (208, 13, 'PVC 와 데이터 유지', '`storage: 50Mi` 의 PVC 를 만들면 상태가 처음에 무엇일까요? Pod 가 쓰고 나면요? 그 Pod 를 지우고 같은 PVC 를 쓰는 새 Pod 를 만들면 파일은요?', '기본 StorageClass 가 Pod 가 생길 때까지 기다리기도 해요.', NULL, NULL, '[]', 'choice', '["PVC 를 만들면 바로 `Bound` 가 된다", "Pod 를 지우면 PVC 의 파일도 함께 사라진다", "이 클러스터에서는 PVC 가 처음에 `Pending` 이고 Pod 가 사용하면 `Bound` 가 된다. Pod 를 지워도 PVC 의 데이터는 남아 새 Pod 에서 같은 파일을 읽을 수 있다", "PVC 는 Pod 가 하나만 쓸 수 있고 파일은 저장되지 않는다"]', 2, 'StorageClass 의 설정에 따라 바로 `Bound` 가 되기도 합니다.', NULL, NULL, NULL, NULL),
  (208, 14, 'emptyDir 의 수명', '한 Pod 의 두 컨테이너가 같은 `emptyDir` 를 마운트했습니다. 한 컨테이너가 파일을 쓰면 다른 컨테이너에서 보일까요? 컨테이너가 재시작되면, Pod 를 지우고 새로 만들면요?', 'emptyDir 는 Pod 에 속해요.', NULL, NULL, '[]', 'choice', '["컨테이너마다 따로 만들어져 서로 보이지 않는다", "같은 Pod 의 컨테이너끼리 공유되어 보인다. 컨테이너가 재시작해도 데이터는 남지만 Pod 를 지우면 사라져 새 Pod 에는 없다", "Pod 를 지워도 데이터가 남는다", "컨테이너가 재시작하면 데이터가 사라진다"]', 1, '남겨야 하는 데이터는 PVC 에 둡니다.', NULL, NULL, NULL, NULL),
  (208, 15, 'ConfigMap 만들기', '`kubectl create` 로 **ConfigMap 을 만드는** 대상 종류를 줄임말이 아닌 긴 이름으로 채우세요.', '"config"와 "map"을 이어요.', NULL, NULL, '[]', 'fill', '["configmap", "confmap", "settings", "params"]', NULL, '줄임말은 `cm` 입니다.', '[0]', 'kubectl create {0} c1 --from-literal=k=v', NULL, NULL),
  (208, 16, '파일로 만들기', '**파일 내용으로** ConfigMap 을 만드는 `--from-` 옵션의 끝부분을 채우세요.', '"파일"을 영어로 써요.', NULL, NULL, '[]', 'fill', '["file", "path", "text", "disk"]', NULL, '키는 기본으로 파일 이름이 됩니다.', '[0]', 'kubectl create cm c2 --from-{0}=app.conf', NULL, NULL),
  (208, 17, 'Secret 종류', '임의의 키와 값으로 Secret 을 만드는 **종류 이름**을 채우세요.', '"일반적인"을 뜻하는 영어예요.', NULL, NULL, '[]', 'fill', '["generic", "opaque", "plain", "basic"]', NULL, '이렇게 만든 Secret 의 type 은 `Opaque` 입니다.', '[0]', 'kubectl create secret {0} s1 --from-literal=user=admin', NULL, NULL),
  (208, 18, '글자로 값 주기', '`kubectl create` 에서 **값을 명령에 직접 적어 주는** 옵션의 끝부분을 채우세요.', '"literal"이에요.', NULL, NULL, '[]', 'fill', '["literal", "value", "text", "string"]', NULL, '키와 값은 `키=값` 으로 씁니다.', '[0]', 'kubectl create secret generic s1 --from-{0}=user=admin', NULL, NULL),
  (208, 19, 'Secret 키 참조', '환경 변수 하나를 **Secret 의 키에서** 가져올 때 `valueFrom` 아래에 쓰는 필드를 채우세요.', '"secret"과 "key"와 "ref"를 이어요.', NULL, NULL, '[]', 'fill', '["secretKeyRef", "secretRef", "secretValue", "secretEnv"]', NULL, 'ConfigMap 은 `configMapKeyRef` 입니다.', '[0]', 'valueFrom: {0}', NULL, NULL),
  (208, 20, '키 전체를 환경 변수로', '`envFrom` 아래에서 **ConfigMap 의 모든 키를 환경 변수로 넣는** 필드를 채우세요.', '"configMap"과 "ref"를 이어요.', NULL, NULL, '[]', 'fill', '["configMapRef", "configMapKeyRef", "configMapEnv", "configMapAll"]', NULL, '`prefix` 를 함께 주면 변수 이름 앞에 붙습니다.', '[0]', 'envFrom: - {0}: name: c4', NULL, NULL),
  (208, 21, '읽기 전용 마운트', '`volumeMounts` 항목을 **읽기 전용으로 만드는** 필드 이름을 채우세요.', '"read"와 "Only"를 이어요.', NULL, NULL, '[]', 'fill', '["readOnly", "readonly", "ro", "locked"]', NULL, '대소문자를 정확히 써야 합니다.', '[0]', 'mountPath: /sec, {0}: true', NULL, NULL),
  (208, 22, '수정 못 하게 잠그기', 'ConfigMap 이나 Secret 의 **데이터를 바꿀 수 없게 잠그는** 필드를 채우세요.', '"바뀌지 않는"을 뜻하는 영어예요.', NULL, NULL, '[]', 'fill', '["immutable", "readOnly", "locked", "frozen"]', NULL, '바꾸려면 지우고 다시 만듭니다.', '[0]', '{0}: true', NULL, NULL),
  (208, 23, '파일 하나만 마운트', '볼륨에서 **파일 하나만 골라** 마운트할 때 쓰는 `volumeMounts` 필드를 채우세요.', '"sub"와 "Path"를 이어요.', NULL, NULL, '[]', 'fill', '["subPath", "subFile", "itemPath", "keyPath"]', NULL, '이렇게 마운트한 파일은 ConfigMap 이 바뀌어도 갱신되지 않습니다.', '[0]', 'mountPath: /one/app.conf, {0}: app.conf', NULL, NULL),
  (208, 24, '파일 권한 정하기', 'Secret 볼륨의 **파일 권한을 정하는** 필드를 채우세요.', '"default"와 "Mode"를 이어요.', NULL, NULL, '[]', 'fill', '["defaultMode", "mode", "fileMode", "perm"]', NULL, '숫자는 `chmod` 와 같은 8진수입니다.', '[0]', 'secretName: s1, {0}: 0400', NULL, NULL),
  (208, 25, 'PVC 줄임말', '`kubectl get` 에서 **PersistentVolumeClaim 의 줄임말**을 채우세요.', '"pv" 에 "c"를 붙여요.', NULL, NULL, '[]', 'fill', '["pvc", "pv", "sc", "cm"]', NULL, '`pv` 는 PersistentVolume 입니다.', '[0]', 'kubectl get {0}', NULL, NULL),
  (208, 26, 'ConfigMap 을 환경 변수로 쓰기', 'ConfigMap 을 만들어 Pod 의 환경 변수로 쓰고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → Pod 정의 → 확인 → 고친 뒤 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl create cm c1 --from-literal=k1=v1` 로 ConfigMap 을 만든다", "Pod 의 `env` 에 `configMapKeyRef` 로 `k1` 을 `K1` 변수로 연결해 만든다", "`kubectl exec p1 -- env` 로 `K1=v1` 이 보이는지 확인한다", "ConfigMap 을 `v1-NEW` 로 고친 뒤에도 실행 중인 Pod 의 `K1` 이 그대로인지 확인한다"]', NULL, '새 값을 쓰려면 Pod 를 다시 시작해야 합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (208, 27, 'Secret 만들고 값 확인', 'Secret 을 만들고 값이 어떻게 저장됐는지 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 조회 → 복원 → 설명 보기 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl create secret generic s1 --from-literal=user=admin` 으로 Secret 을 만든다", "`kubectl get secret s1 -o jsonpath=''{.data.user}''` 로 `YWRtaW4=` 가 나오는지 본다", "그 값을 `base64 -d` 로 되돌려 `admin` 이 나오는지 확인한다", "`kubectl describe secret s1` 에는 값 대신 바이트 수만 나오는지 확인한다"]', NULL, 'base64 는 암호화가 아니므로 Secret 읽기 권한을 제한해야 합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (208, 28, '설정 파일을 볼륨으로 마운트', 'ConfigMap 을 파일로 마운트하고 고쳤을 때 반영되는지 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 마운트 → 확인 → 고치고 기다려 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl create cm c2 --from-file=app.conf` 로 ConfigMap 을 만든다", "Pod 에 `configMap` 볼륨을 `/cfg` 로 마운트해 만든다", "`kubectl exec p1 -- cat /cfg/app.conf` 로 파일 내용을 확인한다", "ConfigMap 을 고치고 잠시 기다린 뒤 같은 `cat` 으로 새 내용으로 바뀌었는지 확인한다"]', NULL, '`subPath` 로 마운트했다면 이 파일은 바뀌지 않습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (208, 29, 'PVC 로 데이터 남기기', 'PVC 에 쓴 데이터가 Pod 를 지워도 남는지 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', 'PVC 만들기 → 쓰는 Pod → Pod 삭제 → 새 Pod 에서 확인 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl apply -f pvc.yaml` 로 PVC 를 만들고 `Pending` 인 것을 본다", "PVC 를 마운트한 Pod 를 만들어 파일을 쓰고 PVC 가 `Bound` 가 되는지 본다", "`kubectl delete pod` 로 Pod 만 지운다", "같은 PVC 를 마운트한 새 Pod 에서 `cat` 으로 파일이 남아 있는지 확인한다"]', NULL, 'Pod 를 지워도 PVC 는 남아 있으므로 같은 데이터를 다시 쓸 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
